) AS a("id", "description", "effects")
WHERE v."status" IN ('published', 'draft')
ON CONFLICT DO NOTHING;
--> statement-breakpoint
-- Les adversaires de donjon ont aussi leurs talents.
UPDATE "balance_settings" SET "data" = jsonb_set("data", '{dungeons,enemyAbilities}', 'true'::jsonb)
WHERE "content_version_id" IN (SELECT "id" FROM "content_versions" WHERE "status" IN ('published', 'draft'))
  AND "data" ? 'dungeons';
